package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class OperationsPermissionGuard {public static final String FEATURE="primehr.operations";private final AdministrativeAuthorizationClient client;public OperationsPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public void require(PrimeHrAction action,String token){var p=client.resolve(FEATURE,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case ARCHIVE->p.canDelete();default->false;};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("PrimeHR operations require agency-wide permission");}}
